import React, { useEffect, useState } from "react";
import Sidebar from "../components/Sidebar";

function Resources() {
  const [sciences, setSciences] = useState([]);
  const [subsciences, setSubsciences] = useState([]);
  const [loading, setLoading] = useState(true);

  const user = JSON.parse(localStorage.getItem("user"));

  useEffect(() => {
    async function fetchResources() {
      try {
        const res = await fetch("http://localhost:8080/resources");
        const data = await res.json();
        setSciences(data.sciences || []);
        setSubsciences(data.subsciences || []);
        setLoading(false);
      } catch (err) {
        console.error("Resources error:", err);
        setLoading(false);
      }
    }

    fetchResources();
  }, []);

  function getSubsciencesForScience(scienceId) {
    return subsciences.filter((s) => s.science_id === scienceId);
  }

  if (!user) {
    return <h1 style={{ color: "white" }}>Please log in</h1>;
  }

  return (
    <div className="dashboard-page">
      <Sidebar />

      <main className="dashboard-main">
        <header className="dashboard-header">
          <div>
            <h1>Start Learning</h1>
            <p className="dashboard-subtitle">
              Choose a science, pick a subscience, and begin your personalized unit.
            </p>
          </div>
        </header>

        {loading ? (
          <p className="dashboard-loading">Loading resources...</p>
        ) : (
          <div className="resources-layout">
            {sciences.map((science) => {
              const subs = getSubsciencesForScience(science.id);

              return (
                <section
                  key={science.id}
                  className={`resources-section resources-${science.code}`}
                >
                  <div className="resources-section-header">
                    <h2>{science.name}</h2>
                    <p>
                      Explore {science.name === "Natural Science" ? "the world around us" : "how people and societies work"}.
                    </p>
                  </div>

                  <div className="resources-subscience-grid">
                    {subs.map((sub) => (
                      <div
                        key={sub.id}
                        className="resources-subscience-card"
                        onClick={() =>
                          (window.location.href = `/subscience/${sub.id}`)
                        }
                      >
                        <h3>{sub.name}</h3>
                        <p className="resources-subscience-code">
                          {science.code.toUpperCase()} • {sub.code.toUpperCase()}
                        </p>
                        <p className="resources-subscience-desc">
                          10-lesson unit • XP, games, tutors, and Q&A.
                        </p>
                      </div>
                    ))}
                  </div>
                </section>
              );
            })}
          </div>
        )}
      </main>
    </div>
  );
}

export default Resources;
